PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,pen_name TEXT,email TEXT UNIQUE,password_hash TEXT,bio TEXT,photo_url TEXT,role TEXT DEFAULT 'author',status TEXT DEFAULT 'active',created_at TEXT DEFAULT (datetime('now')),updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,token_hash TEXT UNIQUE,expires_at TEXT,created_at TEXT DEFAULT (datetime('now')),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,content TEXT NOT NULL,category TEXT DEFAULT 'poem',language TEXT DEFAULT 'ne',cover_image TEXT,status TEXT DEFAULT 'draft',created_at TEXT DEFAULT (datetime('now')),updated_at TEXT DEFAULT (datetime('now')),author_id INTEGER,FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS library_authors(id INTEGER PRIMARY KEY AUTOINCREMENT,author_slug TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL,pen_name TEXT,photo_url TEXT,biography TEXT,birth_date TEXT,death_date TEXT,region TEXT,language TEXT DEFAULT 'ne',is_featured INTEGER DEFAULT 0,created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS library_works(id INTEGER PRIMARY KEY AUTOINCREMENT,source_id TEXT,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,author_name TEXT,author_slug TEXT,language TEXT DEFAULT 'ne',genre TEXT NOT NULL DEFAULT 'poem',text_content TEXT,source_name TEXT,source_url TEXT,rights_status TEXT NOT NULL DEFAULT 'review',license TEXT,attribution TEXT,published_year INTEGER,region TEXT,tradition TEXT,collector_name TEXT,notes TEXT,translation_status TEXT,created_at TEXT DEFAULT (datetime('now')),FOREIGN KEY(author_slug) REFERENCES library_authors(author_slug) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_posts_public ON posts(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_library_public ON library_works(rights_status,created_at DESC);
